Map<String, dynamic> galleryLibraryText(String language) =>
    Map<String, dynamic>.from(
        galleryLabelData['ui'][language] ?? galleryLabelData['ui']['en-US']);
String localizedGalleryTag(String tag, String language) =>
    galleryLabelData['names'][tag.trim().toLowerCase().replaceAll('_', ' ')]
        ?['labels']?[language] ??
    tag;
String galleryTagQuery(String query, String language) {
  final matches = (galleryLabelData['names'] as Map)
      .entries
      .where((e) => e.value['labels'][language] == query.trim())
      .toList();
  return matches.length == 1 ? matches.single.key : query;
}
